func (s *scan) digitRun() int {
	var n int = int(0)
	for {
		var b string = s.buf
		var j int = s.i
		for ((j < len(b)) && (b[j] >= uint8(48))) && (b[j] <= uint8(57)) {
			j = (j + int(1))
		}
		n = (n + (j - s.i))
		s.i = j
		b_1 := (j < len(b))
		if !b_1 {
			v := (s).fill()
			b_1 = (!v)
		}
		if b_1 {
			return n
		}
	}
}

